import {TRACKS,PRESETS,newSong,clone,validateSong,encodeSong,decodeSong,wheelState,validateCore,rootFor,noteName} from './music.js';
import {Engine,renderWav} from './audio.js';
const $=id=>document.getElementById(id);
let song=newSong(),follow=true,pitchMode=false,live={state:'unknown'},settlement=null,coreIssue='Connecting to Sepolia',statusData=null,coreCheckedAt=0,coreMovedAt=0,lastSafe=null,selectedPreset='burrow',master=.7;
let deployment=null,nextStatusAt=0,nextCoreAt=0,polling=false,toastTimer,undo=null;
let sessions=[];
try{const v=JSON.parse(localStorage.getItem('squeek-orchestra-v1')||'[]');if(Array.isArray(v))sessions=v.slice(0,12).filter(x=>{try{validateSong(x.song);return typeof x.id==='string'&&typeof x.savedAt==='string';}catch{return false;}});}catch{}
const engine=new Engine(()=>song,paintStep,applySignal);
function el(tag,className,text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4300);}
function modal(title){$('modal-title').textContent=title;$('modal-body').replaceChildren();if(!$('modal').open)$('modal').showModal();return $('modal-body');}
function closeModal(){$('modal').close();}
$('close-modal').onclick=closeModal;
$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function persist(){try{localStorage.setItem('squeek-orchestra-v1',JSON.stringify(sessions));$('saved-count').textContent=sessions.length;return true;}catch{toast('Browser storage is unavailable. Use a composition link or WAV to keep your music.');return false;}}
$('saved-count').textContent=sessions.length;
const stepButtons=[];
for(let step=0;step<16;step++)$('step-numbers').append(el('span','',String(step+1).padStart(2,'0')));
TRACKS.forEach((track,t)=>{
 const row=el('div','track');row.style.setProperty('--track',track.color);row.dataset.track=t;
 const label=el('div','instrument'),mute=el('button','mute',track.symbol);mute.type='button';mute.title=`Mute ${track.name}`;mute.setAttribute('aria-label',`Mute ${track.name}`);mute.onclick=()=>{song.muted[t]=!song.muted[t];renderTrack(t);};
 const desc=el('button','track-details');desc.title=`Mix ${track.name}`;desc.style.padding='0';desc.style.textAlign='left';desc.append(el('span','track-name',track.name),el('span','track-subtitle',track.subtitle));desc.onclick=()=>openMixer(t);label.append(mute,desc);
 const steps=el('div','steps');stepButtons[t]=[];
 for(let s=0;s<16;s++){const button=el('button','step');button.type='button';button.dataset.step=s;button.dataset.track=t;button.addEventListener('click',e=>editStep(t,s,e.shiftKey));button.addEventListener('contextmenu',e=>{e.preventDefault();if(t>=3)openPitch(t,s);});button.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();stepButtons[t][(s+(e.key==='ArrowRight'?1:15))%16].focus();}else if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();stepButtons[(t+(e.key==='ArrowDown'?1:5))%6][s].focus();}});stepButtons[t][s]=button;steps.append(button);}
 row.append(label,steps);$('tracks').append(row);
});
const pitchButton=el('button','text-button','Pitch mode: off');pitchButton.id='pitch-mode';pitchButton.setAttribute('aria-pressed','false');pitchButton.style.marginLeft='auto';pitchButton.style.marginRight='15px';$('clear').before(pitchButton);pitchButton.onclick=()=>{pitchMode=!pitchMode;pitchButton.textContent=`Pitch mode: ${pitchMode?'on':'off'}`;pitchButton.setAttribute('aria-pressed',String(pitchMode));if(pitchMode)toast('Click bass, keys or bell steps to cycle through five notes and silence.');};
function editStep(t,s,shift){const old=song.pattern[t][s];song.pattern[t][s]=(t>=3&&(pitchMode||shift))?(old>=4?-1:old+1):(old>=0?-1:0);selectedPreset='';renderTrack(t);renderPreset();if(song.pattern[t][s]>=0)engine.preview(t,song.pattern[t][s],song);}
function renderTrack(t){const row=$('tracks').children[t];row.classList.toggle('muted',song.muted[t]);row.querySelector('.mute').setAttribute('aria-pressed',String(song.muted[t]));for(let s=0;s<16;s++){const b=stepButtons[t][s],v=song.pattern[t][s];b.classList.toggle('on',v>=0);b.setAttribute('aria-pressed',String(v>=0));let note=v>=0&&t>=3?noteName(rootFor(song.toneSeed)+(t===3?-12:t===5?12:0)+[0,3,5,7,10][v]):'';b.textContent=note;b.setAttribute('aria-label',`${TRACKS[t].name} step ${s+1}: ${v<0?'off':note||'on'}`);b.title=t>=3?'Click to toggle · Pitch mode to change note':'';}}
function renderPreset(){document.querySelectorAll('[data-preset]').forEach(b=>{b.classList.toggle('active',b.dataset.preset===selectedPreset);b.setAttribute('aria-pressed',String(b.dataset.preset===selectedPreset));});}
function renderSong(){for(let t=0;t<6;t++)renderTrack(t);$('song-name').value=song.name;$('tempo').value=song.bpm;$('key').textContent=noteName(rootFor(song.toneSeed)).replace(/\d/g,'')+' minor';renderPreset();}
function paintStep(step){document.querySelectorAll('.step.current').forEach(b=>b.classList.remove('current'));if(step>=0){stepButtons.forEach(row=>row[step].classList.add('current'));$('audio-status').textContent=`Playing · step ${String(step+1).padStart(2,'0')} / 16`;}else $('audio-status').textContent='Ready when you are';}
function applySignal(){if(!follow)return;let changed=false;if(live.state!=='unknown'){if(song.bpm!==live.bpm||song.ambience!==(live.state==='resting')){song.bpm=live.bpm;song.ambience=live.state==='resting';changed=true;}}if(settlement&&!coreIssue&&song.toneSeed!==settlement.seed){song.toneSeed=settlement.seed;changed=true;}if(changed)renderSong();}
function setFollow(value){follow=value;$('follow').checked=value;if(!value){song.ambience=false;}else if(!engine.running)applySignal();renderStatus();}
$('follow').onchange=e=>{setFollow(e.target.checked);toast(follow?'The wheel takes the lead at the next bar.':'You set the pace. Live data stays visible.');};
$('tempo').addEventListener('change',()=>{const n=Number($('tempo').value);if(!Number.isFinite(n)||n<50||n>160){$('tempo').value=song.bpm;toast('Choose a tempo between 50 and 160 BPM.');return;}song.bpm=Math.round(n);setFollow(false);$('tempo').value=song.bpm;});
$('song-name').addEventListener('change',()=>{song.name=$('song-name').value.trim().slice(0,48)||'Untitled session';$('song-name').value=song.name;});
$('master').oninput=e=>{master=Number(e.target.value)/100;engine.setVolume(master);$('master-value').textContent=e.target.value+'%';};
async function togglePlay(){const b=$('play');if(engine.running){engine.stop();document.body.classList.remove('playing');$('play-label').textContent='Play session';$('play-symbol').textContent='▶';return;}b.disabled=true;try{await engine.start();document.body.classList.add('playing');$('play-label').textContent='Pause session';$('play-symbol').textContent='Ⅱ';}catch(e){engine.stop();toast(e.message);}finally{b.disabled=false;}}
$('play').onclick=togglePlay;
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!$('modal').open&&!['INPUT','BUTTON','TEXTAREA','SELECT','A'].includes(e.target.tagName)){e.preventDefault();togglePlay();}});
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{undo=clone(song);song=newSong(b.dataset.preset);selectedPreset=b.dataset.preset;setFollow(false);renderSong();toast(`${song.name} loaded. Studio tempo · switch on Follow the wheel to go live.`);});
$('clear').onclick=()=>{const body=modal('Start with silence?');body.append(el('p','','Clear all 96 steps in this session. You can restore the pattern immediately afterward.'));const b=el('button','modal-action','Clear pattern');b.onclick=()=>{undo=clone(song);song.pattern=song.pattern.map(r=>r.map(()=>-1));selectedPreset='';renderSong();closeModal();toast('Pattern cleared. Use Undo to restore it.');$('clear').textContent='Undo clear';$('clear').onclick=restorePattern;};body.append(b);};
const clearHandler=$('clear').onclick;
function restorePattern(){if(undo){song=undo;undo=null;renderSong();toast('Pattern restored.');}$('clear').textContent='Clear pattern';$('clear').onclick=clearHandler;}
function openMixer(t){const body=modal(`${TRACKS[t].name} mixer`);body.append(el('p','','Adjust this instrument without changing the other tracks.'));const input=el('input');input.type='range';input.min=0;input.max=100;input.value=Math.round(song.volumes[t]*100);input.style.width='100%';input.setAttribute('aria-label',`${TRACKS[t].name} volume`);const val=el('p','',`${input.value}%`);input.oninput=()=>{song.volumes[t]=Number(input.value)/100;val.textContent=input.value+'%';};body.append(input,val);if(t>=3)body.append(el('p','','Turn on Pitch mode above the grid, then tap a step to cycle its note. Right-click a melodic step to pick a note directly.'));}
function openPitch(t,s){const body=modal(`${TRACKS[t].name} · step ${s+1}`);const choices=el('div','pitch-picker');for(let n=-1;n<5;n++){const b=el('button','',n<0?'Silent':noteName(rootFor(song.toneSeed)+(t===3?-12:t===5?12:0)+[0,3,5,7,10][n]));b.onclick=()=>{song.pattern[t][s]=n;selectedPreset='';renderSong();closeModal();};choices.append(b);}body.append(choices);}
$('save').onclick=()=>{const body=modal('Keep this session');body.append(el('p','','Save a musical snapshot in this browser: notes, mixer, tempo and harmony. Saved sessions reopen in studio mode.'));const input=el('input','modal-field');input.value=song.name;input.maxLength=48;input.setAttribute('aria-label','Saved session name');const button=el('button','modal-action','Save session');button.onclick=()=>{const saved=clone(song);saved.name=input.value.trim()||'Untitled session';const previous=[...sessions];sessions.unshift({id:crypto.randomUUID(),savedAt:new Date().toISOString(),song:saved});sessions=sessions.slice(0,12);if(persist()){closeModal();toast('Session saved in this browser.');}else sessions=previous;};body.append(input,button);};
function openLibrary(){const body=modal('Your sessions');body.append(el('p','',sessions.length?'Your latest 12 sessions, stored on this device. Shared links and WAV files travel with you.':'A quiet shelf, for now. Save your first session with the bookmark button beside its name.'));for(const entry of sessions){const row=el('div','saved-row'),desc=el('div');desc.append(el('strong','',entry.song.name),el('small','',`${entry.song.bpm} BPM · ${new Date(entry.savedAt).toLocaleDateString()}`));const load=el('button','','Load');load.onclick=()=>{song=validateSong(entry.song);follow=false;$('follow').checked=false;selectedPreset='';renderSong();renderStatus();closeModal();toast('Saved musical snapshot loaded.');};const remove=el('button','','Delete');remove.setAttribute('aria-label',`Delete ${entry.song.name}`);remove.onclick=()=>{const old=[...sessions];sessions=sessions.filter(x=>x.id!==entry.id);if(persist()){openLibrary();}else sessions=old;};row.append(desc,load,remove);body.append(row);}}
$('open-library').onclick=openLibrary;
$('share').onclick=()=>{const url=new URL(location.href);url.hash='song='+encodeSong(song);const body=modal('Send a little soundtrack');body.append(el('p','','This link contains your notes, mixer, tempo and current harmony. It opens as a frozen musical snapshot; the listener can choose to follow the wheel.'));const input=el('input','modal-field');input.readOnly=true;input.value=url.href;input.setAttribute('aria-label','Composition link');input.onclick=()=>input.select();const button=el('button','modal-action','Copy composition link');button.onclick=async()=>{try{await navigator.clipboard.writeText(url.href);button.textContent='Copied ✓';toast('Composition link copied.');}catch{input.focus();input.select();toast('Select and copy the link above.');}};body.append(input,button,el('p','','The link works for people who have access to this site. No account or wallet is embedded in it.'));};
$('export').onclick=async()=>{const button=$('export');button.disabled=true;const snapshot=clone(song),original=button.innerHTML;button.textContent='Rendering four bars…';try{const blob=await renderWav(snapshot,master),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=(snapshot.name.replace(/[^a-z0-9_-]+/gi,'-').replace(/^-|-$/g,'')||'squeek-orchestra')+'.wav';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('WAV exported · four bars plus a natural sound tail.');}catch{toast('WAV rendering is unavailable in this browser. Save or share the session instead.');}finally{button.innerHTML=original;button.disabled=false;}};
$('open-about').onclick=()=>{const body=modal('A duet with Squeektoshi');body.innerHTML='<p>A real hamster runs a sensor-equipped wheel. Squeekchain records its accepted wheel activity and settles it on Ethereum Sepolia. You turn that signal into music.</p><ol><li><strong>Write your rhythm.</strong> Tap steps to turn them on or off. Use Pitch mode for bass, keys and bells. Tap an instrument name to open its mixer.</li><li><strong>Choose who leads.</strong> Studio mode gives you a fixed tempo. Follow the wheel uses fresh telemetry: resting plays at 66 BPM with softer instruments; running maps RPM into 72–150 BPM.</li><li><strong>Let harmony evolve.</strong> A deterministic hash of the confirmed round and cumulative work selects a minor pentatonic key. Changes apply at bar boundaries. The round is not used as secure randomness.</li><li><strong>Keep the moment.</strong> Save locally, share the composition link, or export four bars of synthesized stereo audio. Shared and saved snapshots preserve the musical state.</li></ol><p>No wallet, tokens, transactions or rewards. An independent community creation; not an official Squeekchain product.</p>';};
$('open-source').onclick=()=>{const body=modal('Behind the signal');const list=el('dl','signal-list');const fields=[['Telemetry',live.state==='unknown'?'Unavailable':`${live.state} · ${live.rpm.toFixed(1)} RPM`],['Measurement source',live.provenance||'Unknown'],['Last measurement',live.receivedAt?new Date(live.receivedAt).toLocaleString():'Unknown'],['Network','Ethereum Sepolia · 11155111'],['Harmony source',coreIssue||'API identities match the pinned deployment'],['Release',deployment?`${deployment.release} · revision ${deployment.revision}`:'Loading'],['Settled round',settlement?.round||'Unknown'],['Cumulative work',settlement?.work||'Unknown'],['Safe Ethereum block',settlement?.safeBlock||'Unknown'],['Last chain check',coreCheckedAt?new Date(coreCheckedAt).toLocaleTimeString():'Unknown'],['Musical seed',song.toneSeed]];for(const [k,v]of fields)list.append(el('dt','',k),el('dd','',v));body.append(list);if(settlement){const p=el('p'),a=el('a','','View settlement transaction ↗');a.href='https://eth-sepolia.blockscout.com/tx/'+settlement.tx;a.target='_blank';a.rel='noopener';p.append(a);body.append(p);}body.append(el('p','warning','Read-only, confirmation-delayed API data. This app checks the API’s reported deployment identities; it does not independently verify Ethereum state. No missing value is treated as zero.'));const p=el('p');const a=el('a','','Official API documentation ↗');a.href='https://docs.squeekchain.com/developers/api/';a.target='_blank';a.rel='noopener';p.append(a);body.append(p);};
function renderStatus(){
 const unknown=live.state==='unknown';$('wheel-title').textContent=unknown?'The signal is quiet':live.state==='resting'?'Squeektoshi is resting':'Squeektoshi is running';$('wheel-subtitle').textContent=unknown?'Studio mode is always here':live.state==='resting'?'Little paws deserve a pause.':'Tiny paws. Excellent rhythm.';$('state-icon').textContent=unknown?'◌':live.state==='resting'?'☾':'ϟ';
 $('rpm').replaceChildren(document.createTextNode(unknown?'— ':live.rpm.toFixed(1)+' '),el('small','','RPM'));
 $('round').textContent=settlement?.round||'—';$('onair-label').textContent=unknown?'NO SIGNAL':live.provenance==='hardware'?'LIVE':'TEST FEED';$('source-badge').textContent=unknown?'UNKNOWN':live.provenance==='hardware'?'SENSOR':live.provenance.toUpperCase();
 let message=follow?(unknown?'Signal unavailable. Holding your last musical settings.':live.state==='resting'?'Rest mode · soft instruments at 66 BPM.':'Wheel-led tempo · changes on the next bar.'):'Studio mode · your tempo, your sound.';
 if(coreIssue)message+=' '+coreIssue;else if(settlement)message+=` Harmony from settled round ${settlement.round}.`;
 $('source-note').textContent=message;document.body.classList.toggle('resting',live.state==='resting');
}
async function request(path){const response=await fetch('https://api.squeekchain.com/v1/'+path,{signal:AbortSignal.timeout(10000),credentials:'omit'});if(!response.ok){const wait=Number(response.headers.get('Retry-After'));const err=new Error(`Service temporarily unavailable (${response.status}).`);err.delay=Number.isFinite(wait)&&wait>0?Math.min(wait*1000,3600000):30000;throw err;}return response.json();}
async function poll(){if(polling||document.hidden)return;polling=true;const now=Date.now();const jobs=[];
 if(now>=nextStatusAt){nextStatusAt=now+15000;jobs.push((async()=>{try{statusData=await request('status');live=wheelState(statusData);}catch(e){statusData=null;live={state:'unknown'};nextStatusAt=Date.now()+Math.max(15000,e.delay||30000);}})());}
 if(now>=nextCoreAt){nextCoreAt=now+30000;jobs.push((async()=>{try{if(!deployment){const r=await fetch('./deployment.json');if(!r.ok)throw Error('Deployment reference unavailable.');deployment=await r.json();}const raw=await request('core'),value=validateCore(raw,deployment);coreCheckedAt=Date.now();if(lastSafe!==value.safeBlock){lastSafe=value.safeBlock;coreMovedAt=Date.now();}if(Date.now()-coreMovedAt>120000)throw Error('Chain indexer is stale. Holding harmony.');settlement=value;coreIssue=value.paused?'Settlement paused. Holding harmony.':'';}catch(e){coreIssue=e.message;nextCoreAt=Date.now()+Math.max(30000,e.delay||30000);}})());}
 await Promise.allSettled(jobs);polling=false;if(!engine.running)applySignal();renderStatus();}
setInterval(()=>{if(statusData){try{live=wheelState(statusData);}catch{live={state:'unknown'};}}if(coreMovedAt&&Date.now()-coreMovedAt>120000)coreIssue='Chain indexer is stale. Holding harmony.';renderStatus();poll();},5000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){poll();if(engine.running&&engine.ctx?.state!=='running'){engine.stop();document.body.classList.remove('playing');$('play-label').textContent='Play session';$('play-symbol').textContent='▶';toast('Audio was suspended. Press Play to resume.');}}});
if(location.hash.startsWith('#song=')){try{song=decodeSong(location.hash.slice(6));follow=false;$('follow').checked=false;selectedPreset='';toast('Shared composition loaded. Press Play to hear it.');}catch(e){toast(e.message);}}
let stageFrame=null;
$('stage-art').append(document.querySelector('.artwork').cloneNode(true));
const spectrumBars=Array.from({length:32},()=>{const b=el('span');$('stage-bars').append(b);return b;});
function stagePaint(){if($('stage').hidden)return;const data=new Uint8Array(64);if(engine.running&&engine.analyser)engine.analyser.getByteFrequencyData(data);spectrumBars.forEach((b,i)=>b.style.height=Math.max(3,data[i*2]/255*95)+'%');$('stage-title').textContent=song.name;$('stage-tempo').textContent=`${song.bpm} BPM · ${noteName(rootFor(song.toneSeed)).replace(/\d/g,'')} minor`;$('stage-play').textContent=engine.running?'Pause session':'Play session';$('stage-signal').textContent=follow?(live.state==='unknown'?'Live signal unavailable · holding the music':`${live.state==='resting'?'Squeektoshi is resting':'Squeektoshi is running'} · ${live.rpm.toFixed(1)} RPM`):'Studio mode · your tempo, your sound';stageFrame=requestAnimationFrame(stagePaint);}
$('open-stage').onclick=()=>{$('stage').hidden=false;document.body.classList.add('stage-open');stagePaint();$('close-stage').focus();};
function closeStage(){$('stage').hidden=true;document.body.classList.remove('stage-open');cancelAnimationFrame(stageFrame);if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});$('open-stage').focus();}
$('close-stage').onclick=closeStage;$('stage-play').onclick=togglePlay;
$('stage-fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else $('stage').requestFullscreen().catch(()=>toast('Full screen is not supported here. Stage view is still ready.'));};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('stage').hidden)closeStage();});
renderSong();poll();
